use vstd::prelude::*;
use vstd::vec::*;

verus! {

fn has_only_one_distinct_element(arr: &Vec<i32>) -> (result: bool)
    ensures
        result == true <==> (
            // For empty or single-element arrays, result is true
            arr.len() <= 1 ||
            // For arrays with 2+ elements, all elements equal the first element
            forall|i: int| 1 <= i && i < arr.len() ==> arr[i] == arr[0]
        ),
        // Alternative ensures clause for clarity:
        // result == true if and only if array has at most one distinct value
        result == true <==> forall|i: int, j: int| 
            0 <= i && i < arr.len() && 0 <= j && j < arr.len() ==> arr[i] == arr[j],
{
    if arr.len() <= 1 {
        return true;
    }
    
    let first = arr[0];
    let mut i: usize = 1;
    
    while i < arr.len()
        invariant
            1 <= i && i <= arr.len(),
            forall|k: int| 1 <= k && k < i ==> arr[k] == first,
    {
        if arr[i] != first {
            return false;
        }
        i = i + 1;
    }
    
    return true;
}

}